// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TextModel) predicate.TextModel {
	return predicate.TextModel(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TextModel) predicate.TextModel {
	return predicate.TextModel(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TextModel) predicate.TextModel {
	return predicate.TextModel(sql.NotPredicates(p))
}
